UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Sta rechtop met je voeten tegen elkaar. Stap met je rechtervoet naar voren in een uitvalspas — voorste knie boven je enkel, achterste knie richting de vloer.","Stap zonder terug te gaan met je achterste voet naar voren, naast je voorste voet. Maak direct een uitvalspas met je linkervoet.","Loop zo afwisselend door voor de opgegeven afstand of het aantal herhalingen."]'), '$.cues_nl', json('["💡 Houd je bovenlichaam rechtop — leun niet naar voren, ook niet als je moe wordt.","Lange passen vragen meer van je bilspieren en flexibiliteit. Korte passen belasten je bovenbenen meer."]')), updated_at_ms = 1794873600000 WHERE slug = 'walking-lunge' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Stand tall with feet together. Step forward with your right foot into a lunge — front knee above ankle, rear knee toward the floor.';
