UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Sta rechtop, voeten op heupbreedte. Breng je gewicht naar je linkerbeen.","Trap je rechterbeen naar voren tot heuphoogte (of een comfortabele hoogte) en houd het redelijk gestrekt. Laat het zakken en wissel.","Verhoog het tempo zodra je balans goed is — zwaai bij elke trap je andere arm mee."]'), '$.cues_nl', json('["💡 Laat je been gecontroleerd zakken — laat het niet terugvallen.","Kijk recht vooruit, niet naar beneden — je balans wordt meteen beter."]')), updated_at_ms = 1794873600000 WHERE slug = 'alternating-front-kick' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Stand tall, feet hip-width. Shift weight to your left leg.';
