UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Sta in vechthouding: linkervoet iets naar voren, knieën zacht, handen omhoog om je gezicht te beschermen.","Sla een combinatie van jab, cross, hoek en uppercut: jab (links recht), cross (rechts recht), hoek (links), uppercut (rechts).","Neem je houding weer aan en herhaal. Draai bij elke krachtstoot je heupen mee en pivoteer op je voeten."]'), '$.cues_nl', json('["💡 Kracht komt uit je heupdraai, niet uit je armen — de stoot begint bij je voeten.","Blijf licht op je voeten tussen de combinaties — blijf in je atletische houding."]')), updated_at_ms = 1794873600000 WHERE slug = 'boxing-combination' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Stand in a fighting stance: left foot slightly forward, knees soft, hands up protecting your face.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Sta rechtop","Breng je gewicht naar links en til je rechterknie zijwaarts op (heuphoogte)","Zet je voet terug en breng je gewicht naar rechts","Til je linkerknie zijwaarts op","Wissel af in een rustig ritme"]'), '$.cues_nl', json('["Til gecontroleerd — niet zwaaien","Houd je standbeen licht gebogen","Heupstabiliteit en lichte cardio"]')), updated_at_ms = 1794873600000 WHERE slug = 'lateral-knee-raise' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 5 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Stand tall';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Breng je handen op gezichtshoogte, ellebogen gebogen, losse vuisten voor je.","Draai je onderarmen ritmisch in een voorwaartse rolbeweging om elkaar heen.","Houd een constant tempo aan en houd je ellebogen op borsthoogte."]'), '$.cues_nl', json('["💡 Uitstekend actief herstel: je hartslag blijft hoog zonder impact.","Voeg klein zijwaarts voetenwerk toe voor meer intensiteit en coördinatie."]')), updated_at_ms = 1794873600000 WHERE slug = 'speed-bag-simulation' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Raise your hands to face level, elbows bent, hands in loose fists in front of you.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga voor een stevige stoel, step of bank staan waarbij je bovenbeen ongeveer 90 graden maakt als je voet erop staat. Zet je hele rechtervoet plat op het oppervlak, ook je hiel.","Duw door je rechterhiel om op te stappen en breng je linkerknie tot heuphoogte terwijl je rechtop op de step komt. Zet niet af met je achterste voet.","Sta bovenaan helemaal rechtop — strek je heup volledig voordat je zakt. Breng dan je linkervoet langzaam en gecontroleerd terug naar de vloer, daarna je rechtervoet.","Doe alle herhalingen rechts en wissel dan naar links, of wissel elke herhaling van been."]'), '$.cues_nl', json('["Duw door de hiel van je voet op de verhoging — de bilspier van dat been doet het werk, niet een afzet van je voet op de vloer.","Zak langzaam — gecontroleerd zakken bouwt meer kracht op dan slordig afstappen.","💡 💡 Pak dumbbells langs je zij zodra het met lichaamsgewicht makkelijk voelt. Maak de step hoger voor een grotere bewegingsuitslag."]')), updated_at_ms = 1794873600000 WHERE slug = 'box-step-up' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Stand in front of a stable chair, step, or bench that places your thigh at or near 90 degrees when your foot is on it. Place your entire right foot flat on the surface — heel included.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Sta rechtop met je voeten tegen elkaar en je handen langs je lichaam.","Spring je voeten uit en zwaai je armen boven je hoofd.","Spring terug naar de start en herhaal in een vast ritme."]'), '$.cues_nl', json('["Land zacht.","Blijf rustig doorademen."]')), updated_at_ms = 1794873600000 WHERE slug = 'jumping-jacks' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Stand tall with feet together and hands at sides.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Begin in een hoge plank met je handen onder je schouders.","Breng één knie naar je borst en wissel snel.","Houd je heupen recht en je rug neutraal."]'), '$.cues_nl', json('["Schouders recht boven je polsen.","Laat je heupen niet op en neer stuiteren."]')), updated_at_ms = 1794873600000 WHERE slug = 'mountain-climbers' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Start in a high plank with hands under shoulders.';
