UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Begin staand, voeten op heupbreedte. Scharnier vanuit je heupen met een vlakke rug tot je handen op scheenhoogte zijn","Duw door je benen en strek je heupen explosief — alsof je recht omhoog springt","Trek zodra je heupen gestrekt zijn krachtig je schouders op en trek je ellebogen hoog en breed","De stang (of je handen) komt tot hoog op je borst. Laat gecontroleerd zakken en begin opnieuw"]'), '$.cues_nl', json('["De kracht komt uit je benen en heupen — je armen begeleiden, ze trekken niet","Houd de stang (of je handen) de hele tijd dicht bij je lichaam","💡 Dit is de eerste trek van een clean — het bouwt de explosieve heupstrekking op die je nodig hebt voor militaire fysieke testen"]')), updated_at_ms = 1794873600000 WHERE slug = 'clean-pull' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Start standing, feet hip-width; hinge at the hips with a flat back to reach your hands to mid-shin height';
