UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Lig op je rug met je knieën gebogen.","Strek één been.","Adem uit en til je heupen van de vloer met je gebogen been.","Houd 1 seconde vast.","Zak en herhaal: 8 per kant."]'), '$.cues_nl', json('["Houd je heupen recht: laat geen kant zakken.","Bouwt stabiliteit op één been op.","De stap na de ondersteunde heupbrug."]')), updated_at_ms = 1794873600000 WHERE slug = 'single-leg-glute-bridge' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 5 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Lie on back, knees bent';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga zitten of staan en til één voet van de vloer.","Maak 10 keer grote cirkels met je voet, met de klok mee.","Draai 10 keer de andere kant op.","Wissel van voet."]'), '$.cues_nl', json('["Strek en buig je voet door de volle bewegingsuitslag.","Helpt bij vocht vasthouden en doorbloeding tijdens de zwangerschap.","Schrijf voor de afwisseling ook letters met je tenen."]')), updated_at_ms = 1794873600000 WHERE slug = 'ankle-mobility-circles' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Sit or stand, lift one foot off the floor';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Leg een handdoek om een stevige deurklink van een gesloten deur die in het slot zit.","Pak in elke hand een uiteinde, loop met je voeten naar de deur en leun achterover.","Trek je borst naar de klink.","Zak gecontroleerd terug."]'), '$.cues_nl', json('["Test eerst of de deur je gewicht houdt.","Hoe verder je voeten naar voren, hoe zwaarder.","💡 Houd je heupen in lijn: laat ze niet doorzakken."]')), updated_at_ms = 1794873600000 WHERE slug = 'towel-door-row' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Loop a towel around a secure door handle on a closed, latched door.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Stap je rechtervoet naar voren, linkervoet achter je op 45°.","Buig je voorste knie tot 90°.","Breng beide armen boven je hoofd.","Houd vast en wissel van kant."]'), '$.cues_nl', json('["Heupen recht naar voren.","Achterste been sterk."]')), updated_at_ms = 1794873600000 WHERE slug = 'warrior-i-pose' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Step right foot forward, left foot back at 45°';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Sta op je rechtervoet met je knie licht gebogen, linkervoet net van de vloer.","Scharnier vanuit je heup naar voren en breng je linkerbeen gestrekt naar achteren als tegengewicht: je lichaam vormt een T.","Reik met je handen naar de vloer (of houd een dumbbell in je rechterhand).","Span je rechterbilspier aan om terug omhoog te komen. Doe alle herhalingen aan één kant voor je wisselt."]'), '$.cues_nl', json('["Beweeg als één geheel: je romp en achterste been gaan samen, als een wip.","Houd je heupen recht naar de vloer: laat de zwevende heup niet openklappen.","💡 Wiebelen is in het begin normaal. Kijk naar een vast punt voor je balans."]')), updated_at_ms = 1794873600000 WHERE slug = 'single-leg-deadlift' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Stand on your right foot, slight bend in the knee, left foot just off the floor';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Lig op je buik en steun op je onderarmen, ellebogen onder je schouders.","Duw je onderarmen in de vloer en til je borst iets op.","Kijk naar voren, nek neutraal.","Houd de positie vast en adem normaal."]'), '$.cues_nl', json('["Een zachte achteroverbuiging, niet geforceerd.","Goed voor je tussenwervelschijven.","Sla over als op je buik liggen oncomfortabel is."]')), updated_at_ms = 1794873600000 WHERE slug = 'sphinx-hold' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Lie face down, prop on forearms, elbows under shoulders';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Zit of sta rechtop. Laat je rechteroor naar je rechterschouder zakken en voel de rek aan de linkerkant.","Rol je kin langzaam naar voren richting je borst en ga door tot je linkeroor naar je linkerschouder zakt.","Maak de boog terug naar het midden. Maak nooit een volledige cirkel door je hoofd naar achteren te brengen: dat drukt je halswervels samen."]'), '$.cues_nl', json('["💡 Alleen de voorste halve cirkel: halve cirkels zijn veilig, volledige cirkels naar achteren niet.","Adem in elke rekpositie en laat het gewicht van je hoofd het werk doen."]')), updated_at_ms = 1794873600000 WHERE slug = 'neck-half-circles' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Sit or stand tall. Drop your right ear toward your right shoulder, feeling the stretch on the left side.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Zet vanuit handen en knieën je tenen neer en duw je heupen omhoog en naar achteren.","Vorm een omgekeerde V.","Duw je hielen richting de vloer.","Buig om en om je knieën (fietsen)."]'), '$.cues_nl', json('["Spreid je vingers wijd.","Laat je hoofd ontspannen tussen je armen hangen."]')), updated_at_ms = 1794873600000 WHERE slug = 'downward-dog' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'From all fours, tuck toes, push hips up and back';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Lig op je rug. Buig één knie met je voet plat. Strek je andere been, til het op en pak het achter je dij vast.","Trek je been rustig naar je toe tot je een prettige rek achter in je dij voelt.","Trek je tenen naar je scheenbeen om ook je kuit en heupzenuw te rekken. Houd vast en wissel van kant."]'), '$.cues_nl', json('["💡 Houd je onderrug plat: laat hem niet van de vloer komen.","Adem naar de rek toe en ontspan bij het uitademen, dan geeft de spier verder mee."]')), updated_at_ms = 1794873600000 WHERE slug = 'lying-hamstring-stretch' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Lie on your back. Bend one knee with foot flat. Extend the other leg and lift it, clasping behind the thigh.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Sta rechtop en zet een grote stap naar voren.","Zak tot je voorste dij bijna horizontaal is en je achterste knie bijna de vloer raakt.","Duw via je voorste hiel terug naar de start.","Herhaal aan de andere kant."]'), '$.cues_nl', json('["Romp rechtop.","Voorste knie boven het midden van je voet."]')), updated_at_ms = 1794873600000 WHERE slug = 'forward-lunge' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Stand tall, step forward into a long stride.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Zit op de vloer met beide knieën in 90 graden: één been voor je (scheen dwars op je romp), één been opzij (scheen evenwijdig aan je romp). Zit rechtop met een neutrale rug.","Draai beide knieën tegelijk naar de andere kant: je voorste been wordt je achterste en andersom. Je heupen draaien mee.","Pauzeer kort in de nieuwe positie, zo rechtop mogelijk, voor je terugdraait. Dat is één herhaling."]'), '$.cues_nl', json('["Laat de draai uit je heupen komen, niet door met je romp te leunen: het doel is heupmobiliteit, niet zwaaien.","Krijg je niet beide schenen pijnvrij op de vloer? Ga dan op een opgevouwen deken zitten om de heuphoek te verkleinen.","💡 💡 Deze oefening vergroot de binnen- en buitenrotatie van je heupen, wat je heupen en onderrug op lange termijn beschermt. Langzaam en bewust werkt veel beter dan snelle herhalingen."]')), updated_at_ms = 1794873600000 WHERE slug = 'ninety-ninety-hip-switch' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Sit on the floor with both knees bent at 90 degrees — one leg in front of you (shin perpendicular to your torso), one leg to the side (shin parallel to your torso). Sit tall with a neutral spine.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Sta rechtop, voeten op schouderbreedte, armen langs je lichaam.","Zak snel in een kwart squat en zwaai je armen naar achteren.","Keer direct om: zwaai je armen omhoog en strek je heupen, knieën en enkels volledig om zo hoog mogelijk te springen.","Land zacht en vang op met je enkels, knieën en heupen.","Kom helemaal tot rust voor de volgende herhaling."]'), '$.cues_nl', json('["Het snelle zakken en afzetten maakt dit een countermovement: gebruik die veerkracht.","Reik met je armen naar het plafond: zo spring je hoger.","💡 Wordt gebruikt bij fitheidstests in het leger en de topsport. Focus op maximale hoogte per sprong, niet op snelheid."]')), updated_at_ms = 1794873600000 WHERE slug = 'counter-movement-jump' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 5 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Stand upright, feet shoulder-width, arms at your sides';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Lig op je rug met je knieën gebogen en voeten plat op de vloer. Houd in elke hand een dumbbell recht boven je borst, armen gestrekt, handpalmen richting je voeten.","Buig je ellebogen en laat de dumbbells gecontroleerd in een boog zakken tot je bovenarmen licht de vloer raken. Houd je ellebogen op zo''n 45 graden van je romp, niet recht opzij.","Druk zonder te veren terug omhoog vanaf de vloer. Adem uit tijdens het drukken. Span bovenin je borst aan.","De vloer begrenst je bewegingsuitslag: dat beschermt je schouder tegen overrekken onderin."]'), '$.cues_nl', json('["Houd je polsen de hele tijd boven je ellebogen: polsen die naar achteren knikken zijn een vormfout en een blessurerisico.","Veer nooit af van de vloer: de pauze en het drukken vanuit stilstand maken deze variant effectief.","💡 💡 Door de kortere bewegingsuitslag dan bij bench press kun je vaak veilig meer volume aan. Uitstekend voor het opbouwen van je bovenste borstspieren."]')), updated_at_ms = 1794873600000 WHERE slug = 'dumbbell-floor-press' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Lie on your back with knees bent, feet flat on the floor. Hold a dumbbell in each hand directly over your chest, arms extended, palms facing your feet.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Zit op handen en knieën, polsen onder je schouders, knieën onder je heupen.","Houd je rechterknie in 90° gebogen.","Trap je rechtervoet richting het plafond en span bovenin je bilspier aan.","Zak zonder de vloer te raken.","15 herhalingen per kant."]'), '$.cues_nl', json('["Houd je heupen recht: niet draaien.","Duw je hiel naar het plafond.","Op handen en knieën is ideaal met een zwangerschapsbuik."]')), updated_at_ms = 1794873600000 WHERE slug = 'donkey-kick' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 5 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'On all fours, wrists under shoulders, knees under hips';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Zak bij het opdrukken helemaal naar de vloer: borst en dijen raken de grond.","Til beide handen kort van de vloer en houd je ellebogen licht naar binnen.","Zet je handen terug en druk je explosief omhoog tot gestrekte armen.","Reset en herhaal: elke herhaling begint vanuit stilstand op de vloer."]'), '$.cues_nl', json('["Het grondcontact dwingt een volledige bewegingsuitslag af: geen halve herhalingen.","Knijp je schouderbladen samen als je je handen optilt.","💡 Dit is de standaard opdrukvariant van de Nederlandse militaire fitheidstest: techniek telt."]')), updated_at_ms = 1794873600000 WHERE slug = 'hand-release-push-up' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Lower yourself fully to the floor in a push-up — chest and thighs touching the ground';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Sta op één voet (houd een muur vast voor balans).","Til je andere been langzaam opzij tot heuphoogte.","Houd 1 seconde vast.","Laat langzaam zakken.","12 herhalingen per kant."]'), '$.cues_nl', json('["Houd je bekken recht.","Trek je tenen naar je toe.","Uitstekend voor een stabiel bekken tijdens de zwangerschap."]')), updated_at_ms = 1794873600000 WHERE slug = 'standing-hip-abduction' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 5 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Stand on one foot (hold wall for balance)';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Start in een hoge plank met je handen onder je schouders.","Span je core aan en houd je lichaam in een rechte lijn.","Laat je borst gecontroleerd naar de vloer zakken.","Druk terug tot gestrekte armen zonder je schouders op te trekken."]'), '$.cues_nl', json('["Ribben omlaag, bilspieren aangespannen.","Ellebogen op ~30-45 graden van je romp.","Nek neutraal."]')), updated_at_ms = 1794873600000 WHERE slug = 'push-up' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Start in a high plank with hands under shoulders.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Zet je voeten op schouderbreedte, tenen licht naar buiten.","Duw je heupen naar achteren en buig je knieën tot je dijen horizontaal zijn.","Houd je borst de hele tijd omhoog en je knieën in lijn met je tenen.","Duw via je hielen terug omhoog."]'), '$.cues_nl', json('["Je gewicht blijft op middenvoet en hiel: laat je hielen niet loskomen.","Je knieën blijven in lijn met je tweede teen.","💡 Beginner: zak tot stoelhoogte. Advanced: voeg onderin een pauze toe."]')), updated_at_ms = 1794873600000 WHERE slug = 'squat' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Stand with feet shoulder-width apart, toes turned out slightly';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Lig op je rug met je knieën gebogen en voeten plat.","Span je core aan en kantel je bekken licht.","Duw via je hielen je heupen omhoog.","Pauzeer, span je bilspieren aan en zak gecontroleerd terug."]'), '$.cues_nl', json('["Maak geen holle onderrug.","Je knieën blijven in lijn met je tenen."]')), updated_at_ms = 1794873600000 WHERE slug = 'glute-bridge' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Lie on back with knees bent and feet flat.';

CREATE TABLE _0126_assert (ok INTEGER NOT NULL CHECK (ok = 1)) STRICT;
INSERT INTO _0126_assert (ok) SELECT CASE WHEN (SELECT COUNT(*) FROM exercises WHERE gym_id IS NULL AND is_active = 1 AND slug IN ('360-breathing', 'standing-twist-march', 'skater-hop', 'walking-lunge', 'heel-dig-march', 'jumping-jack', 'shadow-boxing', 'alternating-front-kick', 'jump-rope-simulation', 'grapevine-step', 'broad-jump', 'boxing-combination', 'lateral-knee-raise', 'speed-bag-simulation', 'box-step-up', 'jumping-jacks', 'mountain-climbers', 'power-step-up-jump', 'speed-skater', 'cross-country-ski-step', 'jump-squat', 'tuck-jump', 'burpee', 'pogo-hops', 'lunge', 'standing-bicycle', 'seated-cardio-punch', 'calf-raise', 'sprint-in-place', 'wide-step-touch', 'march-in-place', 'clean-pull', 'pike-push-up', 'bear-crawl', 'reverse-plank', 'plank-shoulder-tap', 'good-morning-bodyweight', 'low-impact-jumping-jacks', 'high-knees', 'shoulder-circles-active', 'inverted-row-feet-elevated', 'stair-climb-simulation', 'plank', 'chest-opener-arms', 'exhalation-core-engagement', 'pelvic-floor-breathing', 'sumo-squat', 'half-kneeling-hip-opener', 'leg-swings-lateral', 'lateral-lunge', 'single-leg-glute-bridge', 'ankle-mobility-circles', 'towel-door-row', 'warrior-i-pose', 'single-leg-deadlift', 'sphinx-hold', 'neck-half-circles', 'downward-dog', 'lying-hamstring-stretch', 'forward-lunge', 'ninety-ninety-hip-switch', 'counter-movement-jump', 'dumbbell-floor-press', 'donkey-kick', 'hand-release-push-up', 'standing-hip-abduction', 'push-up', 'squat', 'glute-bridge')
  AND json_valid(instructions_json)
  AND json_array_length(instructions_json, '$.steps_nl') = json_array_length(instructions_json, '$.steps')
  AND json_array_length(instructions_json, '$.cues_nl') = COALESCE(json_array_length(instructions_json, '$.cues'), 0)) = 69 THEN 1 ELSE 0 END;
DROP TABLE _0126_assert;
